let reservation=null;let currentRow=null;let currentPage=1;let rowsPerPage=10;let allRows=[];let tableConfig={colIndices:{name:null,sport:0,court:1,date:2,time:3},hasNameSearch:!1,isAdmin:!1};function initReservations(config){tableConfig={...tableConfig,...config};document.addEventListener('DOMContentLoaded',function(){const tbody=document.getElementById('tableBody');if(tbody){allRows=Array.from(tbody.querySelectorAll('tr'));updatePagination()}})}
function updatePagination(){const filteredRows=allRows.filter((row)=>row.style.display!=='none');const totalPages=Math.ceil(filteredRows.length/rowsPerPage);allRows.forEach((row)=>row.classList.add('pagination-hidden'));const start=(currentPage-1)*rowsPerPage;const end=start+rowsPerPage;const rowsToShow=filteredRows.slice(start,end);rowsToShow.forEach((row)=>row.classList.remove('pagination-hidden'));document.getElementById('showingFrom').textContent=filteredRows.length>0?start+1:0;document.getElementById('showingTo').textContent=Math.min(end,filteredRows.length);document.getElementById('totalRecords').textContent=filteredRows.length;document.getElementById('prevBtn').disabled=currentPage===1;document.getElementById('nextBtn').disabled=currentPage===totalPages||totalPages===0;generatePageNumbers(totalPages);disableLateReservations()}
function generatePageNumbers(totalPages){const pageNumbersDiv=document.getElementById('pageNumbers');pageNumbersDiv.innerHTML='';if(totalPages<=7){for(let i=1;i<=totalPages;i++){pageNumbersDiv.appendChild(createPageButton(i))}}else{pageNumbersDiv.appendChild(createPageButton(1));if(currentPage>3){pageNumbersDiv.appendChild(createDots())}
let startPage=Math.max(2,currentPage-1);let endPage=Math.min(totalPages-1,currentPage+1);for(let i=startPage;i<=endPage;i++){pageNumbersDiv.appendChild(createPageButton(i))}
if(currentPage<totalPages-2){pageNumbersDiv.appendChild(createDots())}
if(totalPages>1){pageNumbersDiv.appendChild(createPageButton(totalPages))}}}
function createPageButton(pageNum){const button=document.createElement('button');button.className='pagination-btn page-number';button.textContent=pageNum;button.onclick=()=>goToPage(pageNum);if(pageNum===currentPage){button.classList.add('active')}
return button}
function createDots(){const span=document.createElement('span');span.className='pagination-dots';span.textContent='...';return span}
function goToPage(page){currentPage=page;updatePagination()}
function goToNextPage(){const filteredRows=allRows.filter((row)=>row.style.display!=='none');const totalPages=Math.ceil(filteredRows.length/rowsPerPage);if(currentPage<totalPages){currentPage++;updatePagination()}}
function goToPreviousPage(){if(currentPage>1){currentPage--;updatePagination()}}
function filterTable(){if(!allRows||allRows[0].cells[0].textContent=="Nessuna prenotazione")return;let searchName='';const searchInput=document.getElementById('searchName');if(tableConfig.hasNameSearch&&searchInput){searchName=searchInput.value.toLowerCase()}
const filterSport=document.getElementById('filterSport').value.toLowerCase();const filterCourt=document.getElementById('filterCourt').value.toLowerCase();const filterDate=document.getElementById('filterDate').value;const rows=document.querySelectorAll('#tableBody tr');rows.forEach((row)=>{const sport=row.cells[tableConfig.colIndices.sport].textContent.toLowerCase();const court=row.cells[tableConfig.colIndices.court].textContent.toLowerCase();const date=row.cells[tableConfig.colIndices.date].textContent;let matchName=!0;if(tableConfig.hasNameSearch&&tableConfig.colIndices.name!==null){const name=row.cells[tableConfig.colIndices.name].textContent.toLowerCase();matchName=name.includes(searchName)}
const matchSport=!filterSport||sport.includes(filterSport);const matchCourt=!filterCourt||court.includes(filterCourt);const matchDate=!filterDate||convertDate(date)===filterDate;if(matchName&&matchSport&&matchCourt&&matchDate){row.style.display=''}else{row.style.display='none'}});currentPage=1;updatePagination()}
function convertDate(dateStr){const parts=dateStr.split('/');if(parts.length===3){return `${parts[2]}-${parts[1]}-${parts[0]}`}
return dateStr}
function resetFilters(){const searchName=document.getElementById('searchName');if(searchName)searchName.value='';document.getElementById('filterSport').value='';document.getElementById('filterCourt').value='';document.getElementById('filterDate').value='';filterTable()}
function changeSport(){const sportSelect=document.getElementById('filterSport');const courtsSelect=document.getElementById('filterCourt');const sport=sportSelect.value;const courts=document.querySelectorAll('#filterCourt option');courtsSelect.value='';courts.forEach((courtOption)=>{if(!courtOption.getAttribute('data-court-id')||(sport!=''&&courtOption.getAttribute('data-court-id').includes(sport))){courtOption.style.display=''}else{courtOption.style.display='none'}});filterTable()}
function openDeleteDialog(id){reservation=id;document.getElementById('dialogDelete').classList.add('active');dialog=document.getElementById('dialogDelete')
dialog.focus();document.getElementById('dialogDelete').addEventListener('click',function(e){if(e.target===this){closeDeleteDialog()}});document.addEventListener('keydown',function(e){if(e.key==='Escape'){closeDeleteDialog()}})}
function closeDeleteDialog(){document.getElementById('dialogDelete').classList.remove('active');reservation=null}
function deleteReservation(){fetch('../controller/deleteReservation.php',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:'idPrenotazione='+encodeURIComponent(reservation)}).then(()=>{location.reload()}).catch((error)=>{console.error('Error:',error)});closeDeleteDialog()}
function openEditDialog(id,button){const currentRow=button.closest('tr');const cells=currentRow.cells;const indices=tableConfig.colIndices;reservation=id;if(!tableConfig.isAdmin){const dateStrCheck=cells[indices.date].textContent;const timeStrCheck=cells[indices.time].textContent.split(' - ')[0];const isoDateCheck=convertDate(dateStrCheck);const reservationDate=new Date(`${isoDateCheck}T${timeStrCheck}:00`);const now=new Date();const limitMs=24*60*60*1000;if(reservationDate-now<limitMs){alert("Non modificabile: mancano meno di 24 ore all'evento.");return}}
const today=new Date();let minDateObj=new Date(today);if(!tableConfig.isAdmin){minDateObj.setDate(today.getDate()+1)}
const minDateString=minDateObj.toISOString().split('T')[0];const dateInput=document.getElementById('editData');if(dateInput){dateInput.setAttribute('min',minDateString)}
const editCliente=document.getElementById('editCliente');if(editCliente&&indices.name!==null){editCliente.value=cells[indices.name].textContent}
document.getElementById('editSport').value=cells[indices.sport].textContent;changeSportDialog();document.getElementById('editCampo').value=cells[indices.court].textContent.split(' ')[1];const dateStr=cells[indices.date].textContent;const dateForInput=convertDate(dateStr);document.getElementById('editData').value=dateForInput;document.getElementById('editOrario').value=cells[indices.time].textContent;changeDateDialog();const dialog=document.getElementById('editDialog');dialog.classList.add('active');dialog.focus();dialog.onclick=function(e){if(e.target===this)closeEditDialog();};document.onkeydown=function(e){if(e.key==='Escape')closeEditDialog();}}
function closeEditDialog(){document.getElementById('editDialog').classList.remove('active');currentRow=null;reservation=null}
function changeSportDialog(){const sportSelect=document.getElementById('editSport');const courtsSelect=document.getElementById('editCampo');const sport=sportSelect.value;const courts=document.querySelectorAll('#editCampo option');courtsSelect.value='';courts.forEach((court)=>{if(!court.getAttribute('data-court-id')||(sport!=''&&court.getAttribute('data-court-id').includes(sport))){court.style.display=''}else{court.style.display='none'}});changeDateDialog()}
function changeDateDialog(){const date=document.getElementById('editData').value;const court=document.getElementById('editCampo').value;const sport=document.getElementById('editSport').value;const timeOptions=document.getElementById('editOrario');if(!date||!court){Array.from(timeOptions.options).forEach((opt)=>{opt.disabled=!1;opt.hidden=!1;opt.style.display=''});return}
const now=new Date();const limitTime=new Date(now.getTime()+24*60*60*1000);const formData=new FormData();formData.append('action','get_slots');formData.append('court',court);formData.append('date',date);formData.append('sport',sport);if(reservation){formData.append('excludeId',reservation)}
fetch('../controller/editReservation.php',{method:'POST',body:formData}).then((response)=>response.json()).then((bookedSlots)=>{Array.from(timeOptions.options).forEach((option)=>{const isBooked=bookedSlots.some((slot)=>slot.trim()===option.value.trim());let isTooSoon=!1;const startTimeString=option.value.split(' - ')[0];if(startTimeString){const slotDate=new Date(`${date}T${startTimeString}`);if(slotDate<limitTime){isTooSoon=!0}}
if(isBooked||isTooSoon){option.disabled=!0;option.style.display=''}else{option.disabled=!1;option.hidden=!1;option.style.display=''}})}).catch((err)=>console.error('Errore recupero orari:',err))}
function resetTime(){document.getElementById('editOrario').value='';changeDateDialog()}
function confirmEdit(){const sport=document.getElementById('editSport').value;const court=document.getElementById('editCampo').value;const data=document.getElementById('editData').value;const timeVal=document.getElementById('editOrario').value;if(!timeVal)return!1;const timeStart=timeVal.split(' - ')[0];const timeEnd=timeVal.split(' - ')[1];editReservation(sport,court,data,timeStart,timeEnd);return!1}
function editReservation(sport,court,date,timeStart,timeEnd){const data=new URLSearchParams();data.append('action','save');data.append('idPrenotazione',reservation);data.append('sport',sport);data.append('court',court);data.append('date',date);data.append('timeStart',timeStart);data.append('timeEnd',timeEnd);fetch('../controller/editReservation.php',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:data}).then(async(response)=>{if(response.ok){location.reload()}}).catch((error)=>{console.error('Error:',error)})}
function disableLateReservations(){if(!allRows||allRows[0].cells[0].textContent=="Nessuna prenotazione")return;const indices=tableConfig.colIndices;const now=new Date();const limitMs=tableConfig.isAdmin?0:24*60*60*1000;allRows.forEach((row)=>{const dateStr=row.cells[indices.date].textContent;const timeStr=row.cells[indices.time].textContent.split(' - ')[0];const isoDate=convertDate(dateStr);const reservationDate=new Date(`${isoDate}T${timeStr}:00`);const diff=reservationDate-now;const editBtn=row.querySelector('.btn-edit');if(editBtn){if(diff<limitMs){editBtn.disabled=!0;editBtn.style.opacity='0.4';editBtn.style.cursor='not-allowed';editBtn.title=tableConfig.isAdmin?'Evento già terminato':'Non modificabile'}else{editBtn.disabled=!1;editBtn.style.opacity='1';editBtn.style.cursor='pointer';editBtn.removeAttribute('title')}}
const deleteBtn=row.querySelector('.btn-delete');if(deleteBtn){if(diff<limitMs){deleteBtn.disabled=!0;deleteBtn.style.opacity='0.4';deleteBtn.style.cursor='not-allowed';deleteBtn.title=tableConfig.isAdmin?'Evento già terminato':'Non modificabile'}else{deleteBtn.disabled=!1;deleteBtn.style.opacity='1';deleteBtn.style.cursor='pointer';deleteBtn.removeAttribute('title')}}})}